class _NamedCeleryTaskDispatcher:
    """Publish by registered task name without importing another worker's task graph."""

    def __init__(self, task_name: str) -> None:
        self.task_name = str(task_name)

    def apply_async(self, *, kwargs: dict[str, Any], queue: str):
        return celery_app.send_task(
            self.task_name,
            kwargs=kwargs,
            queue=queue,
        )


